$vanna$, $vanna${"name": "albums", "columns": [{"name": "album_id", "type": "INTEGER", "is_primary_key": true}, {"name": "title", "type": "VARCHAR", "description": "Album title."}, {"name": "artist_id", "type": "INTEGER", "is_hidden": true}], "description": "One row per album. The only bridge between a track and its artist.", "table_reference": "chinook.album"}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.247315+00:00$vanna$, $vanna$2026-08-25 06:23:10.247315+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (7, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/education-analytics.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$fb59247eedb720866e37e4f305c6e0720c65f59cf41de576e697cf384f9e5e39$vanna$, $vanna$# Conventions for student records. The cohort rule is the one that most often
# turns a retention problem into a retention success, and it does it silently.

id: education-analytics
name: Education analytics
description: >-
  Census-date enrolment, cohorts that must not be redefined, and grades that
  are categories rather than numbers.

instructions:
  - text: >-
      Enrolment is counted as of a census date, not continuously. A count taken
      on any other day picks up late withdrawals and misses late registrations,
      and will not reconcile with anything the institution has published.
    priority: 62

  - text: >-
      A cohort is fixed when it is formed. Retention and completion follow the
      original members wherever they go; recomputing the cohort from whoever is
      still present is how a retention rate reaches one hundred per cent.
    priority: 58

  - text: >-
      A grade is often an ordered category rather than a number. Averaging
      letter grades needs a stated mapping, and a mapping that differs from the
      institution's own produces a figure nobody recognises.
    priority: 54

  - text: >-
      A student can be enrolled on several programmes and can attempt a course
      more than once. Say whether a figure counts students, enrolments or
      attempts, because all three answers look equally plausible.
    priority: 49

  - text: >-
      Small groups identify individuals even with no name in the result.
      Suppress any cell below an agreed threshold rather than publishing a
      group of two, and say that suppression was applied.
    priority: 45
$vanna$, $vanna${"id": "education-analytics", "name": "Education analytics", "description": "Census-date enrolment, cohorts that must not be redefined, and grades that are categories rather than numbers.", "instructions": [{"text": "Enrolment is counted as of a census date, not continuously. A count taken on any other day picks up late withdrawals and misses late registrations, and will not reconcile with anything the institution has published.", "priority": 62}, {"text": "A cohort is fixed when it is formed. Retention and completion follow the original members wherever they go; recomputing the cohort from whoever is still present is how a retention rate reaches one hundred per cent.", "priority": 58}, {"text": "A grade is often an ordered category rather than a number. Averaging letter grades needs a stated mapping, and a mapping that differs from the institution's own produces a figure nobody recognises.", "priority": 54}, {"text": "A student can be enrolled on several programmes and can attempt a course more than once. Say whether a figure counts students, enrolments or attempts, because all three answers look equally plausible.", "priority": 49}, {"text": "Small groups identify individuals even with no name in the result. Suppress any cell below an agreed threshold rather than publishing a group of two, and say that suppression was applied.", "priority": 45}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.075403+00:00$vanna$, $vanna$2026-08-25 06:23:10.075403+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (8, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/finance-conventions.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$aea70895207cbd01a5e93bff691013c5c0826dc66669c9101c8c8dcadc4cb69e$vanna$, $vanna$# Conventions that hold in most finance and billing schemas.
#
# A starter pack is a starting point, not a subscription. Enabling it copies these
# rules into the workspace, which then owns and may edit them; removing the pack
# later takes back only the copies nobody has touched.
#
# The first rule here used to be hardcoded into every new workspace by
# `Platform._seed_knowledge`. It is a business assumption -- true of a great many
# schemas and false in some -- so it belongs behind an explicit choice rather than
# being seeded into workspaces whose data it does not describe.

id: finance-conventions
name: Finance conventions
description: >-
  Currency units, fiscal calendar, and the difference between an invoiced amount
  and a recognised one.

instructions:
  - text: >-
      Monetary columns whose name ends in _cents store integer cents. Divide by
      100.0 and label the result in dollars.
    priority: 60

  - text: >-
      "Revenue" means the sum of line-level amounts unless someone asks
      specifically about invoice or order totals. The two differ whenever an
      invoice carries discounts, tax or shipping that are not attributed to a line.
    priority: 55

  - text: >-
      Exclude cancelled, refunded and test transactions from revenue figures
      unless the question is explicitly about them, and say in the answer that you
      did.
    priority: 55

  - text: >-
      A trailing twelve months window ends at the most recent complete month, not
      at today. A partial current month makes every trend look like a collapse.
    priority: 50
$vanna$, $vanna${"id": "finance-conventions", "name": "Finance conventions", "description": "Currency units, fiscal calendar, and the difference between an invoiced amount and a recognised one.", "instructions": [{"text": "Monetary columns whose name ends in _cents store integer cents. Divide by 100.0 and label the result in dollars.", "priority": 60}, {"text": "\"Revenue\" means the sum of line-level amounts unless someone asks specifically about invoice or order totals. The two differ whenever an invoice carries discounts, tax or shipping that are not attributed to a line.", "priority": 55}, {"text": "Exclude cancelled, refunded and test transactions from revenue figures unless the question is explicitly about them, and say in the answer that you did.", "priority": 55}, {"text": "A trailing twelve months window ends at the most recent complete month, not at today. A partial current month makes every trend look like a collapse.", "priority": 50}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.084147+00:00$vanna$, $vanna$2026-08-25 06:23:10.084147+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (9, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/healthcare-operations.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$229eff9ee53ae48365c62dcf2728284c860afb62b417f6a216caaffb1f9f4b73$vanna$, $vanna$# Conventions for clinical and administrative health data. The privacy rules
# here are deliberately about how to report rather than about what is permitted
# -- that is a matter for the deployment, and a pack cannot know it.

id: healthcare-operations
name: Healthcare operations
description: >-
  Attendance against intent, the encounter as the unit of activity, and
  reporting clinical work without reporting a person.

instructions:
  - text: >-
      An appointment that did not happen still has a row, and a status column
      is what separates activity from intent. Count attendance explicitly
      rather than counting rows, and name the statuses that were included.
    priority: 62

  - text: >-
      Clinical activity can be reported without reporting a person. Aggregate
      to the clinician, department or period, and where a question cannot be
      answered without naming a patient beside a condition, say so rather than
      answering it.
    priority: 58

  - text: >-
      A small count identifies somebody even when no name appears in the
      result. Suppress cells below an agreed threshold and state that the
      suppression happened.
    priority: 54

  - text: >-
      The encounter is the unit of activity, and orders, results and charges
      hang off it. Counting any of them per patient needs the encounter in
      between, and one encounter can carry several of each.
    priority: 49

  - text: >-
      A clinician's speciality is not their seniority and is not their
      department. The three correlate closely enough to be mistaken for one
      another, so say which one a breakdown is by.
    priority: 45
$vanna$, $vanna${"id": "healthcare-operations", "name": "Healthcare operations", "description": "Attendance against intent, the encounter as the unit of activity, and reporting clinical work without reporting a person.", "instructions": [{"text": "An appointment that did not happen still has a row, and a status column is what separates activity from intent. Count attendance explicitly rather than counting rows, and name the statuses that were included.", "priority": 62}, {"text": "Clinical activity can be reported without reporting a person. Aggregate to the clinician, department or period, and where a question cannot be answered without naming a patient beside a condition, say so rather than answering it.", "priority": 58}, {"text": "A small count identifies somebody even when no name appears in the result. Suppress cells below an agreed threshold and state that the suppression happened.", "priority": 54}, {"text": "The encounter is the unit of activity, and orders, results and charges hang off it. Counting any of them per patient needs the encounter in between, and one encounter can carry several of each.", "priority": 49}, {"text": "A clinician's speciality is not their seniority and is not their department. The three correlate closely enough to be mistaken for one another, so say which one a breakdown is by.", "priority": 45}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.094420+00:00$vanna$, $vanna$2026-08-25 06:23:10.094420+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (10, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/hospitality-operations.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$6dc5f09817f2c5b07ca1683960688de253c02918b6e0b07ca31049e6c32d1a75$vanna$, $vanna$# Conventions for accommodation data. Occupancy and revenue per available room
# are ratios whose denominators are easy to get wrong and impossible to spot
# afterwards, which is what most of this pack is about.

id: hospitality-operations
name: Hotels and hospitality
description: >-
  Occupancy denominators, rate against yield, and why a cancelled booking still
  carries a price.

instructions:
  - text: >-
      Occupancy is room nights sold over room nights available, so it needs the
      inventory as a denominator. A count of reservations divided by a count of
      rooms is not occupancy and will not agree with anything the property
      reports.
    priority: 62

  - text: >-
      Average daily rate is revenue over room nights sold; revenue per
      available room is revenue over room nights available. They answer
      different questions, and only the second one falls when the hotel is
      empty.
    priority: 58

  - text: >-
      A cancelled booking usually keeps its rate and its dates. Revenue has to
      exclude it while a cancellation rate has to include it, so the same table
      filtered two ways gives both figures.
    priority: 54

  - text: >-
      A stay is counted in nights, not days. Arriving and departing on the same
      date is zero nights, and the departure date is not a night sold.
    priority: 49

  - text: >-
      The date a booking was made and the dates it covers are different axes.
      Demand analysis groups by the booking date and occupancy by the stay
      date, and mixing them produces a seasonality curve that belongs to
      neither.
    priority: 45
$vanna$, $vanna${"id": "hospitality-operations", "name": "Hotels and hospitality", "description": "Occupancy denominators, rate against yield, and why a cancelled booking still carries a price.", "instructions": [{"text": "Occupancy is room nights sold over room nights available, so it needs the inventory as a denominator. A count of reservations divided by a count of rooms is not occupancy and will not agree with anything the property reports.", "priority": 62}, {"text": "Average daily rate is revenue over room nights sold; revenue per available room is revenue over room nights available. They answer different questions, and only the second one falls when the hotel is empty.", "priority": 58}, {"text": "A cancelled booking usually keeps its rate and its dates. Revenue has to exclude it while a cancellation rate has to include it, so the same table filtered two ways gives both figures.", "priority": 54}, {"text": "A stay is counted in nights, not days. Arriving and departing on the same date is zero nights, and the departure date is not a night sold.", "priority": 49}, {"text": "The date a booking was made and the dates it covers are different axes. Demand analysis groups by the booking date and occupancy by the stay date, and mixing them produces a seasonality curve that belongs to neither.", "priority": 45}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.103112+00:00$vanna$, $vanna$2026-08-25 06:23:10.103112+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (11, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/logistics-operations.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$4596e04b8623bc2766b61a96114e06b5844743d9acca3666609ae1cdaec9530f$vanna$, $vanna$# Conventions for shipment and delivery data. The first one is the rule most
# often broken by accident, and it flatters the operation every single time.

id: logistics-operations
name: Logistics and delivery
description: >-
  What on-time is measured against, transit versus dwell, and choosing between
  consignments, parcels and scans.

instructions:
  - text: >-
      On time means delivered against the promise made at booking, not against
      the latest estimate. Comparing with an estimate that was revised while
      the shipment ran late makes almost everything on time.
    priority: 62

  - text: >-
      Transit is movement and dwell is waiting. Total lead time is both, and a
      delay attributed to transit when it was really dwell sends people to fix
      the wrong part of the network.
    priority: 58

  - text: >-
      A shipment holds many parcels and a parcel is scanned many times. Decide
      whether the question is about consignments, packages or scan events
      before aggregating, because the three counts differ by an order of
      magnitude.
    priority: 54

  - text: >-
      A shipment still in flight has no delivery date. Dropping those rows
      measures only what has already arrived -- the population most likely to
      have arrived on time -- so count them as unresolved instead.
    priority: 50

  - text: >-
      Weight and volume are both billable and the larger of the two governs. A
      cost per kilogram that ignores volumetric weight understates the freight
      on anything light and bulky.
    priority: 45
$vanna$, $vanna${"id": "logistics-operations", "name": "Logistics and delivery", "description": "What on-time is measured against, transit versus dwell, and choosing between consignments, parcels and scans.", "instructions": [{"text": "On time means delivered against the promise made at booking, not against the latest estimate. Comparing with an estimate that was revised while the shipment ran late makes almost everything on time.", "priority": 62}, {"text": "Transit is movement and dwell is waiting. Total lead time is both, and a delay attributed to transit when it was really dwell sends people to fix the wrong part of the network.", "priority": 58}, {"text": "A shipment holds many parcels and a parcel is scanned many times. Decide whether the question is about consignments, packages or scan events before aggregating, because the three counts differ by an order of magnitude.", "priority": 54}, {"text": "A shipment still in flight has no delivery date. Dropping those rows measures only what has already arrived -- the population most likely to have arrived on time -- so count them as unresolved instead.", "priority": 50}, {"text": "Weight and volume are both billable and the larger of the two governs. A cost per kilogram that ignores volumetric weight understates the freight on anything light and bulky.", "priority": 45}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.113087+00:00$vanna$, $vanna$2026-08-25 06:23:10.113087+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (12, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/manufacturing-operations.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$0f92bc696928f92a60f35eb1aeae09de55cea84fb654881d8e9c3e6cf4ea49e7$vanna$, $vanna$# Conventions for production and shop-floor data. Each of these is a place where
# a reasonable-looking aggregate describes a healthier line than the one that is
# actually running.

id: manufacturing-operations
name: Manufacturing operations
description: >-
  Yield against output, downtime against planned running time, and where a
  rework unit gets counted twice.

instructions:
  - text: >-
      Units started and units accepted are different measures. Yield is
      accepted divided by started, so reporting output without scrap makes a
      failing line look productive.
    priority: 62

  - text: >-
      Downtime only means something against planned running time. A line idle
      because nothing was scheduled is not a failure, and averaging the two
      together hides the failures that matter.
    priority: 58

  - text: >-
      Rework is neither a good unit nor a scrapped one. Count it in its own
      right, or the same physical item is counted twice: once when it failed
      and once when it passed.
    priority: 54

  - text: >-
      A bill of materials is a hierarchy and component usage multiplies down
      its levels. Consumption per finished unit needs the whole explosion, not
      the top level's immediate children.
    priority: 49

  - text: >-
      A work order spans a date range and can cross a shift, a day and a
      reporting period. Attribute output to the period it completed in and say
      so, because attributing by start date moves output between months.
    priority: 45
$vanna$, $vanna${"id": "manufacturing-operations", "name": "Manufacturing operations", "description": "Yield against output, downtime against planned running time, and where a rework unit gets counted twice.", "instructions": [{"text": "Units started and units accepted are different measures. Yield is accepted divided by started, so reporting output without scrap makes a failing line look productive.", "priority": 62}, {"text": "Downtime only means something against planned running time. A line idle because nothing was scheduled is not a failure, and averaging the two together hides the failures that matter.", "priority": 58}, {"text": "Rework is neither a good unit nor a scrapped one. Count it in its own right, or the same physical item is counted twice: once when it failed and once when it passed.", "priority": 54}, {"text": "A bill of materials is a hierarchy and component usage multiplies down its levels. Consumption per finished unit needs the whole explosion, not the top level's immediate children.", "priority": 49}, {"text": "A work order spans a date range and can cross a shift, a day and a reporting period. Attribute output to the period it completed in and say so, because attributing by start date moves output between months.", "priority": 45}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.125620+00:00$vanna$, $vanna$2026-08-25 06:23:10.125620+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (13, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/retail-operations.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$ba1c1be98a605eacf0b5ce42b0c9f67b8b340091d59989d8699d2bdf3c2052ab$vanna$, $vanna$# Conventions for store and basket data. Complements finance-conventions rather
# than repeating it: that pack defines what revenue is, this one defines the
# denominators retail measures get divided by.

id: retail-operations
name: Retail and storefront
description: >-
  Returns as negative sales, comparable-store rules, and the traffic
  denominator a conversion rate needs.

instructions:
  - text: >-
      A return is a negative sale, not a missing one. Net revenue subtracts
      returns in the period they came back, and reporting gross as though it
      were net overstates every category with a high return rate.
    priority: 62

  - text: >-
      Comparable growth compares only the stores trading in both periods.
      Including an opening or a closure attributes a change in the estate to a
      change in trade.
    priority: 58

  - text: >-
      The basket is the unit a shopper controls. Average basket value and items
      per basket are per transaction, so computing either per line inflates
      both.
    priority: 54

  - text: >-
      A conversion rate needs a traffic denominator from the same place and
      period as the transactions. Without one, report transactions and say that
      conversion cannot be computed from this data.
    priority: 49

  - text: >-
      Discounts, loyalty redemptions and gift cards each reduce what was
      collected without reducing what was sold. Say which of those two a
      revenue figure represents.
    priority: 45
$vanna$, $vanna${"id": "retail-operations", "name": "Retail and storefront", "description": "Returns as negative sales, comparable-store rules, and the traffic denominator a conversion rate needs.", "instructions": [{"text": "A return is a negative sale, not a missing one. Net revenue subtracts returns in the period they came back, and reporting gross as though it were net overstates every category with a high return rate.", "priority": 62}, {"text": "Comparable growth compares only the stores trading in both periods. Including an opening or a closure attributes a change in the estate to a change in trade.", "priority": 58}, {"text": "The basket is the unit a shopper controls. Average basket value and items per basket are per transaction, so computing either per line inflates both.", "priority": 54}, {"text": "A conversion rate needs a traffic denominator from the same place and period as the transactions. Without one, report transactions and say that conversion cannot be computed from this data.", "priority": 49}, {"text": "Discounts, loyalty redemptions and gift cards each reduce what was collected without reducing what was sold. Say which of those two a revenue figure represents.", "priority": 45}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.135911+00:00$vanna$, $vanna$2026-08-25 06:23:10.135911+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (14, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/warehouse-inventory.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$a1ded8a3067a921977b1627cbc2b57bcb1a541356a7601d8ab215947e31038fb$vanna$, $vanna$# Conventions for stock and location data. Inventory is the classic case of a
# measure that is a level rather than a sum, and almost every wrong inventory
# number comes from treating it as the latter.

id: warehouse-inventory
name: Warehousing and inventory
description: >-
  On hand against available, reconciling a ledger with a snapshot, and why
  stock cannot be added up over a month.

instructions:
  - text: >-
      On hand is not available. Stock committed to an order is physically
      present and cannot be sold, so an availability figure that reports on
      hand promises inventory that is already gone.
    priority: 62

  - text: >-
      Inventory is a level at a moment. Stock for last month means the balance
      on a stated date, and adding up daily balances produces a number with no
      meaning at all.
    priority: 58

  - text: >-
      A movement ledger and a stock snapshot answer different questions and
      drift apart. Reconcile them before reporting either, and say which of the
      two a figure came from.
    priority: 54

  - text: >-
      The same item in two locations is two rows. Aggregate to the grain the
      question asks about, because a total that mixes site with bin counts the
      same pallet more than once.
    priority: 49

  - text: >-
      Days of cover compares stock against a consumption rate, so it needs a
      stated window for that rate. Computed against an unusual week it is a
      forecast of that week repeating.
    priority: 45
$vanna$, $vanna${"id": "warehouse-inventory", "name": "Warehousing and inventory", "description": "On hand against available, reconciling a ledger with a snapshot, and why stock cannot be added up over a month.", "instructions": [{"text": "On hand is not available. Stock committed to an order is physically present and cannot be sold, so an availability figure that reports on hand promises inventory that is already gone.", "priority": 62}, {"text": "Inventory is a level at a moment. Stock for last month means the balance on a stated date, and adding up daily balances produces a number with no meaning at all.", "priority": 58}, {"text": "A movement ledger and a stock snapshot answer different questions and drift apart. Reconcile them before reporting either, and say which of the two a figure came from.", "priority": 54}, {"text": "The same item in two locations is two rows. Aggregate to the grain the question asks about, because a total that mixes site with bin counts the same pallet more than once.", "priority": 49}, {"text": "Days of cover compares stock against a consumption rate, so it needs a stated window for that rate. Computed against an unusual week it is a forecast of that week repeating.", "priority": 45}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.146508+00:00$vanna$, $vanna$2026-08-25 06:23:10.146508+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (15, $vanna$global$vanna$, $vanna$$vanna$, $vanna$$vanna$, $vanna$instructions/packs/workforce-analytics.yml$vanna$, $vanna$instruction_pack$vanna$, $vanna$.yml$vanna$, $vanna$081476d2e72f1c710ad79cea921b5eead2be0e1e288de27cad7bc793c66cf125$vanna$, $vanna$# Conventions for HR and people data, written to be schema-agnostic so that they
# suit a workspace whose employee tables look nothing like the sample one.

id: workforce-analytics
name: Workforce analytics
description: >-
  Headcount as of a date, the denominator attrition needs, and dated attributes
  that each change on their own schedule.

instructions:
  - text: >-
      Headcount is a figure as of a date. A count over a period is either an
      average of daily headcount or the balance on a stated day -- never a
      count of everyone who appeared at any point, which counts a replacement
      twice.
    priority: 62

  - text: >-
      Attrition is leavers over average headcount for the same period, not over
      the closing figure. Dividing by the closing headcount makes a shrinking
      team's attrition look better the more people leave.
    priority: 58

  - text: >-
      Pay is personal. Report it as an aggregate over a group large enough to
      conceal an individual, and never beside a name unless the question is
      explicitly about one named person.
    priority: 54

  - text: >-
      A role, a grade and a reporting line each change on their own date. Their
      department means the one held on the date the question is about, which is
      rarely the one held now.
    priority: 49

  - text: >-
      Contractors, part-timers and people on leave are all employed, and none
      of them is one full-time equivalent. Say whether a headcount counts heads
      or FTE.
    priority: 45
$vanna$, $vanna${"id": "workforce-analytics", "name": "Workforce analytics", "description": "Headcount as of a date, the denominator attrition needs, and dated attributes that each change on their own schedule.", "instructions": [{"text": "Headcount is a figure as of a date. A count over a period is either an average of daily headcount or the balance on a stated day -- never a count of everyone who appeared at any point, which counts a replacement twice.", "priority": 62}, {"text": "Attrition is leavers over average headcount for the same period, not over the closing figure. Dividing by the closing headcount makes a shrinking team's attrition look better the more people leave.", "priority": 58}, {"text": "Pay is personal. Report it as an aggregate over a group large enough to conceal an individual, and never beside a name unless the question is explicitly about one named person.", "priority": 54}, {"text": "A role, a grade and a reporting line each change on their own date. Their department means the one held on the date the question is about, which is rarely the one held now.", "priority": 49}, {"text": "Contractors, part-timers and people on leave are all employed, and none of them is one full-time equivalent. Say whether a headcount counts heads or FTE.", "priority": 45}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.155866+00:00$vanna$, $vanna$2026-08-25 06:23:10.155866+00:00$vanna$);
