$vanna$, $vanna${"name": "sales", "measures": [{"name": "revenue", "type": "DOUBLE", "expression": "SUM(grand_total)", "description": "Total order value in dollars."}, {"name": "order_count", "type": "BIGINT", "expression": "COUNT(*)"}], "dimensions": [{"name": "status", "expression": "status"}, {"name": "region", "expression": "ship_region"}], "base_object": "orders", "description": "Order revenue."}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.172829+00:00$vanna$, $vanna$2026-08-25 06:23:10.172829+00:00$vanna$);
