INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (26, $vanna$project$vanna$, $vanna$chinook$vanna$, $vanna$chinook$vanna$, $vanna$projects/chinook/models/artists/metadata.yml$vanna$, $vanna$model$vanna$, $vanna$.yml$vanna$, $vanna$a413b62413d7a645f58ee766a08ed05a1ec5020cb0bfe4f9d75af314b87c3ab7$vanna$, $vanna$name: artists
description: >-
  A recording artist or band. Reached from a sale only through
