$vanna$, $vanna${"name": "chinook", "dialect": "postgres", "description": "Semantic layer over the chinook sample database.", "fanout_guard": "warn", "schema_version": 1}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.213649+00:00$vanna$, $vanna$2026-08-25 06:23:10.213649+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (22, $vanna$project$vanna$, $vanna$chinook$vanna$, $vanna$chinook$vanna$, $vanna$projects/chinook/cubes/sales.yml$vanna$, $vanna$cube$vanna$, $vanna$.yml$vanna$, $vanna$74a1c6a56c689011dfab3a9d54a5ea47b859ceb9d54919370f5d7894ee2209d2$vanna$, $vanna$# Invoice-level revenue.
#
# `total` is the amount on the invoice itself, so this cube answers "how much
# did we bill" and groups it by where and when. Anything below invoice level --
# per track, album, artist or genre -- must use the track_sales cube instead,
# because an invoice's total fans out across its lines.
name: sales
base_object: invoices
description: Revenue as invoiced to customers.
measures:
  - name: revenue
    expression: SUM(total)
    type: DOUBLE
    description: Total invoiced, in dollars.
  - name: invoice_count
    expression: COUNT(*)
    type: BIGINT
  - name: average_invoice
    expression: AVG(total)
    type: DOUBLE
dimensions:
  - name: country
    expression: billing_country
  - name: city
    expression: billing_city
time_dimensions:
  - name: invoiced_on
    expression: invoice_date
$vanna$, $vanna${"name": "sales", "measures": [{"name": "revenue", "type": "DOUBLE", "expression": "SUM(total)", "description": "Total invoiced, in dollars."}, {"name": "invoice_count", "type": "BIGINT", "expression": "COUNT(*)"}, {"name": "average_invoice", "type": "DOUBLE", "expression": "AVG(total)"}], "dimensions": [{"name": "country", "expression": "billing_country"}, {"name": "city", "expression": "billing_city"}], "base_object": "invoices", "description": "Revenue as invoiced to customers.", "time_dimensions": [{"name": "invoiced_on", "expression": "invoice_date"}]}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.221530+00:00$vanna$, $vanna$2026-08-25 06:23:10.221530+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (23, $vanna$project$vanna$, $vanna$chinook$vanna$, $vanna$chinook$vanna$, $vanna$projects/chinook/cubes/track_sales.yml$vanna$, $vanna$cube$vanna$, $vanna$.yml$vanna$, $vanna$be2344d8fa62ad36068cb4ef9c4a85f3c74c506d51a5893acea0204a987babb9$vanna$, $vanna$# Line-level revenue: the number that can be attributed to a track.
#
# This is the cube behind "which artists earn the most". The sum is over
# unit_price * quantity on the line, never over invoices.total, which belongs
# to the whole invoice and would be counted once per line it contains.
name: track_sales
base_object: invoice_lines
description: Revenue attributed to individual tracks, and through them to artists.
measures:
  - name: revenue
    expression: SUM(unit_price * quantity)
    type: DOUBLE
    description: Line revenue in dollars. The definition of revenue below invoice level.
  - name: units_sold
    expression: SUM(quantity)
    type: BIGINT
  - name: line_count
    expression: COUNT(*)
    type: BIGINT
    description: Number of sale lines, which is not the same as units sold.
$vanna$, $vanna${"name": "track_sales", "measures": [{"name": "revenue", "type": "DOUBLE", "expression": "SUM(unit_price * quantity)", "description": "Line revenue in dollars. The definition of revenue below invoice level."}, {"name": "units_sold", "type": "BIGINT", "expression": "SUM(quantity)"}, {"name": "line_count", "type": "BIGINT", "expression": "COUNT(*)", "description": "Number of sale lines, which is not the same as units sold."}], "base_object": "invoice_lines", "description": "Revenue attributed to individual tracks, and through them to artists."}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.231074+00:00$vanna$, $vanna$2026-08-25 06:23:10.231074+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (24, $vanna$project$vanna$, $vanna$chinook$vanna$, $vanna$chinook$vanna$, $vanna$projects/chinook/knowledge/rules/general.md$vanna$, $vanna$knowledge_rule$vanna$, $vanna$.md$vanna$, $vanna$ddc8f8c7efd0ec432482bea3c99653683787c4c0ef27711171a97afb0af8a834$vanna$, $vanna$---
title: Conventions
scope: global
priority: 10
---

- `total` and `unit_price` are already in dollars; do not divide.
- Track length is stored in milliseconds; use the `minutes` column instead.
