          "isHidden": true
        },
        {
          "name": "media_type_id",
          "type": "INTEGER",
          "isCalculated": false,
          "notNull": false,
          "isPrimaryKey": false,
          "isHidden": true
        },
        {
          "name": "unit_price",
          "type": "NUMERIC",
          "description": "List price in dollars.",
          "isCalculated": false,
          "notNull": false,
          "isPrimaryKey": false,
          "isHidden": false
        },
        {
          "name": "milliseconds",
          "type": "INTEGER",
          "isCalculated": false,
          "notNull": false,
          "isPrimaryKey": false,
          "isHidden": true
        },
        {
          "name": "minutes",
          "type": "DOUBLE",
          "description": "Track length in minutes. Nobody asks for milliseconds.",
          "expression": "milliseconds / 60000.0",
          "isCalculated": true,
          "notNull": false,
          "isPrimaryKey": false,
          "isHidden": false
        },
        {
          "name": "bytes",
          "type": "INTEGER",
          "isCalculated": false,
          "notNull": false,
          "isPrimaryKey": false,
          "isHidden": true
        },
        {
          "name": "megabytes",
          "type": "DOUBLE",
          "description": "File size in MB.",
          "expression": "bytes / 1048576.0",
          "isCalculated": true,
          "notNull": false,
          "isPrimaryKey": false,
          "isHidden": false
        }
      ],
      "rowLevelAccessControls": []
    }
  ],
  "relationships": [
    {
      "name": "artist_albums",
      "models": [
        "artists",
        "albums"
      ],
      "joinType": "ONE_TO_MANY",
      "condition": "artists.artist_id = albums.artist_id",
      "description": "An artist has many albums."
    },
    {
      "name": "album_tracks",
      "models": [
        "albums",
        "tracks"
      ],
      "joinType": "ONE_TO_MANY",
      "condition": "albums.album_id = tracks.album_id",
      "description": "The only path from a track to its artist."
    },
    {
      "name": "genre_tracks",
      "models": [
        "genres",
        "tracks"
      ],
      "joinType": "ONE_TO_MANY",
      "condition": "genres.genre_id = tracks.genre_id"
    },
    {
      "name": "media_type_tracks",
      "models": [
        "media_types",
        "tracks"
      ],
      "joinType": "ONE_TO_MANY",
      "condition": "media_types.media_type_id = tracks.media_type_id"
    },
    {
      "name": "track_sales",
      "models": [
        "tracks",
        "invoice_lines"
      ],
      "joinType": "ONE_TO_MANY",
      "condition": "tracks.track_id = invoice_lines.track_id",
      "description": "Every sale of a track. Summing track.unit_price here would be wrong."
    },
    {
      "name": "invoice_items",
      "models": [
