INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (52, $vanna$project$vanna$, $vanna$demo$vanna$, $vanna$demo$vanna$, $vanna$projects/demo/models/tracks/metadata.yml$vanna$, $vanna$model$vanna$, $vanna$.yml$vanna$, $vanna$cacc529e34b30b46a9a4902b9f2bad7863fc3881ef5b512e0412b66f04d37786$vanna$, $vanna$name: tracks
description: >-
  One row per track in the catalogue. Length and file size are stored in
  milliseconds and bytes; the calculated columns below are what people mean.
table_reference: chinook.track
columns:
  - name: track_id
    type: INTEGER
    is_primary_key: true
  - name: name
    type: VARCHAR
    description: Track title.
  - name: composer
    type: VARCHAR
  - name: album_id
    type: INTEGER
    is_hidden: true
  - name: genre_id
    type: INTEGER
    is_hidden: true
  - name: media_type_id
    type: INTEGER
    is_hidden: true
  - name: unit_price
    type: NUMERIC
    description: List price in dollars.
  - name: milliseconds
    type: INTEGER
    is_hidden: true
  - name: minutes
    type: DOUBLE
    is_calculated: true
    expression: milliseconds / 60000.0
    description: Track length in minutes. Nobody asks for milliseconds.
  - name: bytes
    type: INTEGER
    is_hidden: true
  - name: megabytes
    type: DOUBLE
    is_calculated: true
    expression: bytes / 1048576.0
    description: File size in MB.
$vanna$, $vanna${"name": "tracks", "columns": [{"name": "track_id", "type": "INTEGER", "is_primary_key": true}, {"name": "name", "type": "VARCHAR", "description": "Track title."}, {"name": "composer", "type": "VARCHAR"}, {"name": "album_id", "type": "INTEGER", "is_hidden": true}, {"name": "genre_id", "type": "INTEGER", "is_hidden": true}, {"name": "media_type_id", "type": "INTEGER", "is_hidden": true}, {"name": "unit_price", "type": "NUMERIC", "description": "List price in dollars."}, {"name": "milliseconds", "type": "INTEGER", "is_hidden": true}, {"name": "minutes", "type": "DOUBLE", "expression": "milliseconds / 60000.0", "description": "Track length in minutes. Nobody asks for milliseconds.", "is_calculated": true}, {"name": "bytes", "type": "INTEGER", "is_hidden": true}, {"name": "megabytes", "type": "DOUBLE", "expression": "bytes / 1048576.0", "description": "File size in MB.", "is_calculated": true}], "description": "One row per track in the catalogue. Length and file size are stored in milliseconds and bytes; the calculated columns below are what people mean.", "table_reference": "chinook.track"}$vanna$, $vanna${}$vanna$, 1, $vanna$seed_database$vanna$, $vanna$2026-08-25 06:23:10.587149+00:00$vanna$, $vanna$2026-08-25 06:23:10.587149+00:00$vanna$);
INSERT INTO vanna_app.config_files (id, scope, tenant_id, project, relative_path, kind, extension, checksum, raw_content, parsed, metadata, version, updated_by, imported_at, updated_at) VALUES (39, $vanna$project$vanna$, $vanna$demo$vanna$, $vanna$demo$vanna$, $vanna$projects/demo/cubes/sales.yml$vanna$, $vanna$cube$vanna$, $vanna$.yml$vanna$, $vanna$74a1c6a56c689011dfab3a9d54a5ea47b859ceb9d54919370f5d7894ee2209d2$vanna$, $vanna$# Invoice-level revenue.
#
# `total` is the amount on the invoice itself, so this cube answers "how much
# did we bill" and groups it by where and when. Anything below invoice level --
# per track, album, artist or genre -- must use the track_sales cube instead,
# because an invoice's total fans out across its lines.
name: sales
base_object: invoices
description: Revenue as invoiced to customers.
measures:
  - name: revenue
    expression: SUM(total)
    type: DOUBLE
    description: Total invoiced, in dollars.
  - name: invoice_count
    expression: COUNT(*)
    type: BIGINT
  - name: average_invoice
    expression: AVG(total)
    type: DOUBLE
dimensions:
  - name: country
    expression: billing_country
  - name: city
    expression: billing_city
time_dimensions:
  - name: invoiced_on
    expression: invoice_date
$vanna$, $vanna${"name": "sales", "measures": [{"name": "revenue", "type": "DOUBLE", "expression": "SUM(total)", "description": "Total invoiced, in dollars."}, {"name": "invoice_count", "type": "BIGINT", "expression": "COUNT(*)"}, {"name": "average_invoice", "type": "DOUBLE", "expression": "AVG(total)"}], "dimensions": [{"name": "country", "expression": "billing_country"}, {"name": "city", "expression": "billing_city"}], "base_object": "invoices", "description": "Revenue as invoiced to customers.", "time_dimensions": [{"name": "invoiced_on", "expression": "invoice_date"}]}$vanna$, $vanna${}$vanna$, 5, $vanna$import_config_files$vanna$, $vanna$2026-08-25 06:23:10.465616+00:00$vanna$, $vanna$2026-08-25 06:56:35.212625+00:00$vanna$);
