  "views": [],
  "cubes": [
    {
      "name": "sales",
      "baseObject": "invoices",
      "description": "Revenue as invoiced to customers.",
      "measures": [
        {
          "name": "revenue",
          "expression": "SUM(total)",
          "type": "DOUBLE",
          "description": "Total invoiced, in dollars."
        },
        {
          "name": "invoice_count",
          "expression": "COUNT(*)",
          "type": "BIGINT"
