      "name": "track_sales",
      "baseObject": "invoice_lines",
      "description": "Revenue attributed to individual tracks, and through them to artists.",
      "measures": [
        {
          "name": "revenue",
          "expression": "SUM(unit_price * quantity)",
          "type": "DOUBLE",
          "description": "Line revenue in dollars. The definition of revenue below invoice level."
        },
        {
          "name": "units_sold",
          "expression": "SUM(quantity)",
          "type": "BIGINT"
        },
        {
          "name": "line_count",
          "expression": "COUNT(*)",
          "type": "BIGINT",
          "description": "Number of sale lines, which is not the same as units sold."
        }
      ],
      "dimensions": [],
      "timeDimensions": []
    }
  ]
}
$vanna$, $vanna${"cubes": [{"name": "sales", "measures": [{"name": "revenue", "type": "DOUBLE", "expression": "SUM(total)", "description": "Total invoiced, in dollars."}, {"name": "invoice_count", "type": "BIGINT", "expression": "COUNT(*)"}, {"name": "average_invoice", "type": "DOUBLE", "expression": "AVG(total)"}], "baseObject": "invoices", "dimensions": [{"name": "country", "type": "VARCHAR", "expression": "billing_country"}, {"name": "city", "type": "VARCHAR", "expression": "billing_city"}], "description": "Revenue as invoiced to customers.", "timeDimensions": [{"name": "invoiced_on", "type": "TIMESTAMP", "expression": "invoice_date"}]}, {"name": "track_sales", "measures": [{"name": "revenue", "type": "DOUBLE", "expression": "SUM(unit_price * quantity)", "description": "Line revenue in dollars. The definition of revenue below invoice level."}, {"name": "units_sold", "type": "BIGINT", "expression": "SUM(quantity)"}, {"name": "line_count", "type": "BIGINT", "expression": "COUNT(*)", "description": "Number of sale lines, which is not the same as units sold."}], "baseObject": "invoice_lines", "dimensions": [], "description": "Revenue attributed to individual tracks, and through them to artists.", "timeDimensions": []}], "views": [], "models": [{"name": "albums", "columns": [{"name": "album_id", "type": "INTEGER", "notNull": false, "isHidden": false, "isCalculated": false, "isPrimaryKey": true}, {"name": "title", "type": "VARCHAR", "notNull": false, "isHidden": false, "description": "Album title.", "isCalculated": false, "isPrimaryKey": false}, {"name": "artist_id", "type": "INTEGER", "notNull": false, "isHidden": true, "isCalculated": false, "isPrimaryKey": false}], "description": "One row per album. The only bridge between a track and its artist.", "tableReference": "chinook.album", "rowLevelAccessControls": []}, {"name": "artists", "columns": [{"name": "artist_id", "type": "INTEGER", "notNull": false, "isHidden": false, "isCalculated": false, "isPrimaryKey": true},