INSERT INTO vanna_app.config_versions (id, config_file_id, version, checksum, raw_content, parsed, source, created_by, note, created_at) VALUES (30, 30, 1, $vanna$bcfbcebbd50f1b2be6063ae6411ac67ce58751634bf68750da1b77a997a1f7bb$vanna$, $vanna$name: invoice_lines
description: >-
  A single track on an invoice. This is where revenue is attributed to a track,
  and therefore the only place an artist's earnings can be computed from.
table_reference: chinook.invoice_line
columns:
  - name: invoice_line_id
    type: INTEGER
    is_primary_key: true
  - name: invoice_id
    type: INTEGER
    is_hidden: true
  - name: track_id
    type: INTEGER
    is_hidden: true
  - name: unit_price
    type: NUMERIC
    description: Price charged for this line, in dollars.
  - name: quantity
    type: INTEGER
  - name: line_revenue
    type: NUMERIC
    is_calculated: true
    expression: unit_price * quantity
    description: >-
      Revenue for this line. Summing this is what "revenue" means for anything
      below invoice level -- an artist, an album, a track or a genre.
