INSERT INTO vanna_app.config_versions (id, config_file_id, version, checksum, raw_content, parsed, source, created_by, note, created_at) VALUES (54, 39, 2, $vanna$257ead534dd6c34844af71567d1a60739da972f28de9e17c0c74cac37c5fa63f$vanna$, $vanna$# Invoice-level revenue.
#
# `total` is the amount on the invoice itself, so this cube answers "how much
# did we bill" and groups it by where and when. Anything below invoice level --
# per track, album, artist or genre -- must use the track_sales cube instead,
# because an invoice's total fans out across its lines.
name: sales
base_object: invoices
description: Revenue as invoiced to customers.
measures:
  - name: revenue
    expression: SUM(total)
    type: DOUBLE
    description: Total invoiced, in dollars.
  - name: invoice_count
    expression: COUNT(*)
    type: BIGINT
  - name: average_invoice
    expression: AVG(total)
    type: DOUBLE
dimensions:
  - name: country
    expression: billing_country
  - name: city
    expression: billing_city
time_dimensions:
  - name: invoiced_on
    expression: invoice_date
  - name: invoice_count
    expression: COUNT(*)
    type: BIGINT
$vanna$, $vanna${"name": "sales", "measures": [{"name": "revenue", "type": "DOUBLE", "expression": "SUM(total)", "description": "Total invoiced, in dollars."}, {"name": "invoice_count", "type": "BIGINT", "expression": "COUNT(*)"}, {"name": "average_invoice", "type": "DOUBLE", "expression": "AVG(total)"}], "dimensions": [{"name": "country", "expression": "billing_country"}, {"name": "city", "expression": "billing_city"}], "base_object": "invoices", "description": "Revenue as invoiced to customers.", "time_dimensions": [{"name": "invoiced_on", "expression": "invoice_date"}, {"name": "invoice_count", "type": "BIGINT", "expression": "COUNT(*)"}]}$vanna$, $vanna$api$vanna$, $vanna$demo@example.com$vanna$, $vanna$added a measure$vanna$, $vanna$2026-08-25 06:38:28.705893+00:00$vanna$);
